<?php
declare(strict_types=1);
require __DIR__.'/../vendor/autoload.php';
use MiniErp\Repositories\StockRepository;
$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$pdo=new PDO("mysql:host={$d['host']};port={$d['port']};dbname=mini_erp_tenant_14;charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$product=(int)$pdo->query('SELECT id FROM produtos ORDER BY id LIMIT 1')->fetchColumn();if($product<1)throw new RuntimeException('No product fixture');$pdo->beginTransaction();try{$repo=new StockRepository($pdo,14);$location=$repo->ensureMainLocation();$code='PENDING-'.bin2hex(random_bytes(4));$pending=$repo->createPendingLot($location,$code,'7.0000',null,date('Y-m-d',strtotime('+1 year')),'NF TEST ONLY','TEST ONLY',999);$row=array_values(array_filter($repo->pendingLots(),fn($item)=>(int)$item['id']===$pending))[0]??null;if(!$row||$row['status']!=='PENDING')throw new RuntimeException('Pending lot not visible');$lot=$repo->linkPendingLot($pending,$product,999);$row=array_values(array_filter($repo->pendingLots(),fn($item)=>(int)$item['id']===$pending))[0]??null;if(!$row||$row['status']!=='LINKED'||(int)$row['linked_lot_id']!==$lot)throw new RuntimeException('Pending lot was not linked');echo"PendingStockLotIntegration OK\n";}finally{$pdo->rollBack();}
